"""Independent file/hash/command readback; no test process or desktop input."""
from pathlib import Path
import argparse,ast,hashlib,json,zipfile
from native_E149_recovery_contract import R,SOURCE,FORMAL,read,sha,encoded,owned,require,check_pins
V=R/'驗證紀錄/current'
def main(master_readback):
 w=read(R/'工作佇列.json');ref=w['current_E149_zombie41_development'];qp=Path(ref['qualification']);require(sha(qp)==ref['qualification_sha256'],'qualification changed');q=read(qp);check_pins(q['source_pins'])
 require(q['status']=='unselected_zombie41_corpse_intent_presented_T_and_window_pair_metadata_only' and q['source_manifest_sha256']==SOURCE and q['formal_target_sha256']==FORMAL and q['compiler_exit_codes']==[0]*18 and (q['changed_files'],q['effective_overlay_files'],q['new_tests_written'],q['retained_skill_tests_written'])==(5,30,14,141),'published source/compiler scope differs')
 require(all(q[k] for k in ['corpse_death_action_lease','live_and_corpse_intent_domains_separate','presented_pixel_T_cycle_and_mouse_choice_integrated','environment_owner_camera_and_visibility_preserved','no_local_corpse_consumption_cost_or_companion_prediction','capacity319_then_effect_not_success','S37_fixed_receipt_position_lifetime_preserved']) and q['new_finite_graphics']==[226] and q['new_opt_in_original_resource_cases']==1 and not q['old_source_success_transferred'],'published behavioral scope differs')
 require(q['tests_executed']==q['new_sessions']==q['desktop_inputs']==q['WAV_playbacks']==0 and not any(q[k] for k in ['PEs_linked','outputs_executed','production_applied','canonical_registry_selected','GUI_verified','whole_goal_complete']),'execution scope differs')
 require(q['canonical_registry_unchanged']==w['current_isolated_development']['candidates'] and q['current_fixture_binding_unchanged']==w['current_E149_fixture_binding'] and q['current_formal_suite_unchanged']==w['current_E149_recovery_suite_development'],'existing control context changed')
 require(not w['active_workloads'] and not w['active_workload_sessions'] and not w['source_and_corresponding_QA_frozen'] and w['current_user_requested_goal']['test_execution_deferred_by_user'] and w['current_user_requested_goal']['desktop_automation_deferred_by_user'],'deferred/idle scope changed')
 cp=Path(q['candidate']);require(sha(cp)==q['candidate_sha256'],'candidate changed');candidate=read(cp);require(len(candidate['effective_overlay_files'])==30 and len(candidate['candidate_files'])==5,'projection count differs');check_pins({candidate['effective_overlay_paths'][n]:h for n,h in candidate['effective_overlay_files'].items()})
 previous=q['previous_break27_dark40_qualification'];require(previous==w['current_E149_break27_dark40_development'] and sha(previous['qualification'])==previous['qualification_sha256'],'prior break27/dark40 source changed');previous=read(previous['qualification']);check_pins(previous['source_pins']);coverage=q['current_source_coverage'];old=previous['current_source_coverage'];require(coverage['recognized_count']==59 and coverage['missing_request_count']==121 and set(coverage['recognized_ids'])==set(old['recognized_ids'])|{41} and set(coverage['missing_request_ids'])==set(old['missing_request_ids'])-{41} and coverage['source_recognition_only'] and not coverage['learned_book_or_runtime_verified'],'request coverage differs')
 require(sha(coverage['request_source'])==coverage['request_source_sha256'] and sha(q['formal_evidence'])==q['formal_evidence_sha256'],'source/proof changed');proof=read(q['formal_evidence']);check_pins(proof['source_pins']);require(proof['definition']==q['definition'] and proof['wire_prefix']==q['wire_prefix']==[20,5,0] and proof['request_bytes']==7 and proof['methods_executed']==0,'formal source differs')
 require(q['next_definition_ids']==proof['next_ids']==[45] and q['next_definition']==proof['next_definition'] and 45 in coverage['missing_request_ids'],'next definition scope differs')
 run=Path(q['compile_run']);require(sha(run/'cohort.json')==q['compile_cohort_sha256'],'cohort changed');c=read(run/'cohort.json');check_pins(c['input_pins']);check_pins(c['normal_product_pins']);require(all(sha(p)==h for p,h in c['external_toolchain_dependency_pins'].items()),'external dependency changed')
 require(c['status']=='eighteen_metadata_compilers_complete_no_tests' and c['owned_process'] is None and not c['outputs_executed'] and not c['PEs_linked'] and c['tests_executed']==0 and not c['module_predecessor_aliases'],'compiler scope differs')
 require([(r['profile'],r['kind']) for r in c['compiler_runs']]==[(p,k) for p in ['Debug','Release'] for k in ['library','library-test','blind20','slow29','advance79','item_spells','magical73','shadow107','object374448']],'compiler target count/order differs')
 WINDOW='LiTo381-Modern/src/modern_lito/native_login_window.rs';pair=q['window_pairing'];require(c['paired_runtime_sources'][WINDOW]==pair and sha(pair['path'])==pair['sha256'] and pair['source']==candidate['effective_overlay_paths'][WINDOW] and sha(pair['source'])==pair['source_sha256'] and len(pair['rewrites'])==1,'window pair differs');raw=Path(pair['source']).read_text('utf-8-sig');previous_wrapper=Path(pair['predecessor']['path']).read_text('utf-8-sig')
 for rewrite in pair['rewrites']:
  require(raw.count(rewrite['original_attribute'])==previous_wrapper.count(rewrite['compiled_attribute'])==1 and sha(rewrite['resolved_path'])==rewrite['resolved_sha256'],'window nested child differs');raw=raw.replace(rewrite['original_attribute'],rewrite['compiled_attribute']);previous_wrapper=previous_wrapper.replace(rewrite['compiled_attribute'],rewrite['original_attribute'])
 require(raw==Path(pair['path']).read_text('utf-8-sig') and previous_wrapper==Path(pair['predecessor']['source']).read_text('utf-8-sig'),'window wrapper has extra edits');old=read(c['original_metadata_cohort']);expected=dict(old['paired_runtime_sources']);require(expected==q['controller_pair_unchanged'] and WINDOW not in expected,'controller nested paths changed');expected[WINDOW]=pair;require(expected==c['paired_runtime_sources'] and sum(len(v['rewrites']) for v in expected.values())==q['original_nested_paths_preserved']==6,'six nested sources differ')
 for row in c['compiler_runs']:
  require(row['exit_code']==0 and row['finished_utc'] and '--emit=metadata' in row['command'] and '--emit=link' not in row['command'] and not row.get('original_handle_cleanup'),'compiler completion differs');check_pins(row['logs']);require(sha(row['product'])==row['product_sha256'] and Path(row['product']).stat().st_size==row['product_bytes'],'metadata changed')
 normal=read(c['base_compiled_inputs']);require(len(normal)==1049,'normal count differs');check_pins({str(R/n):h for n,h in normal.items()});base=read(w['current_development_typecheck_qualification']['qualification']);check_pins(base['normal_product_pins']);require(base['normal_product_pins']==c['normal_product_pins'],'normal products differ')
 evidence=Path(w['last_goal_turn_evidence']);e=read(evidence);rb=read(evidence.with_name('readback.json'));require(evidence.parent==qp.parent and sha(evidence)==rb['evidence_sha256'] and e['qualification_sha256']==sha(qp) and len(rb['after_files'])==8,'checkpoint evidence changed');check_pins({str(R/n):h for n,h in rb['after_files'].items()})
 with zipfile.ZipFile(qp.parent/'before.zip') as z:require(all(hashlib.sha256(z.read(n)).hexdigest().upper()==h for n,h in rb['before_files'].items()),'before archive differs')
 require(sha(e['raw_archive'])==e['raw_archive_sha256'],'raw archive changed')
 with zipfile.ZipFile(e['raw_archive']) as z:
  expected={'qualified-development.json':qp,'cohort.json':run/'cohort.json','candidate.json':cp,'contract.json':Path(q['contract']),'previous-break27-dark40-qualification.json':Path(q['previous_break27_dark40_qualification']['qualification'])}
  expected['compiled-source/paired-runtime-native_login_window.rs']=Path(pair['path'])
  expected.update({'source-pins/'+Path(p).relative_to(R).as_posix():Path(p) for p in q['source_pins']});expected.update({'candidate/'+n:cp.parent/n for n in candidate['candidate_files']})
  for row in c['compiler_runs']:
   for p in row['logs']:expected[row['profile']+'-'+row['kind']+'/'+Path(p).name]=Path(p)
  require(all(hashlib.sha256(z.read(n)).hexdigest().upper()==sha(p) for n,p in expected.items()),'raw archive member differs')
 master=R.parent/'LiTo381-總開發報告.md';latest=owned(master_readback.resolve(strict=True),V/'master-report-current-work');report=read(latest);require(sha(master)==report['after_sha256'],'master changed');body=master.read_text('utf-8-sig');require(all(s in body for s in ['測試與桌面操作暫緩','#41造屍術與屍體選取候選來源已補','新14（13純含合成owner像素＋1原資源opt-in）＋前141案','#45',str(qp).replace('\\','/')]),'master report is not current')
 ast.parse(Path(__file__).read_text('utf-8-sig'));result=dict(status='independent_files_hashes_and_commands_read_back_no_tests',qualification=str(qp),qualification_sha256=sha(qp),normal_inputs=1049,overlay_files=30,metadata_compilers=18,tests_executed=0,desktop_inputs=0,normal_PEs_unchanged=True,eight_checkpoints={n:sha(R/n) for n in rb['after_files']},raw_archive_sha256=sha(e['raw_archive']),master_report=str(master),master_report_sha256=sha(master),master_report_lines=len(body.splitlines()),readback_source_sha256=sha(Path(__file__)),whole_goal_complete=False)
 (qp.parent/'final-readback.json').write_bytes(encoded(result));print(json.dumps(result,ensure_ascii=False))
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--master-readback',required=True,type=Path);main(p.parse_args().master_readback)
